export const bug_hunt_seeds = [{"id":"bug_hunt:seed:0","domain":"Task Management Backend","files":[{"name":"validators.py","content":"import datetime\n\n\ndef validate_task(title, description, priority, due_date):\n    errors = []\n    if not title or len(title.strip()) == 0:\n        errors.append('Title is required')\n    if description and len(description) > 500:\n        errors.append('Description too long')\n    if priority not in ('low', 'medium', 'high', 'critical'):\n        errors.append('Invalid priority')\n    if isinstance(due_date, str):\n        try:\n            due_date = datetime.datetime.strptime(due_date, '%Y-%m-%d').date()\n        except ValueError:\n            errors.append('Invalid due_date format')\n    if isinstance(due_date, datetime.date):\n        if due_date < datetime.date.today():\n            errors.append('Due date must be in the future')\n    return errors\n"},{"name":"store.py","content":"import datetime\n\n\nclass TaskStore:\n    def __init__(self, tasks=None):\n        self.tasks = tasks if tasks is not None else []\n        self._next_id = 1\n\n    def add(self, task):\n        task['id'] = self._next_id\n        self._next_id += 1\n        self.tasks.append(task)\n        return task\n\n    def get(self, task_id):\n        for t in self.tasks:\n            if t['id'] == task_id:\n                return t\n        return None\n\n    def list_by_priority(self):\n        order = {'critical': 4, 'high': 3, 'medium': 2, 'low': 1}\n        return sorted(self.tasks, key=lambda t: order.get(t['priority'], 0), reverse=True)\n\n    def overdue(self):\n        today = datetime.date.today()\n        result = []\n        for t in self.tasks:\n            if t.get('due_date') and t['due_date'] < today:\n                result.append(t)\n        return result\n\n    def complete(self, task_id):\n        task = self.get(task_id)\n        if task is None:\n            raise ValueError('Task not found')\n        task['completed'] = True\n        task['completed_at'] = datetime.datetime.now()\n        return task\n\n    def summary(self):\n        counts = {}\n        for t in self.tasks:\n            p = t['priority']\n            counts[p] = counts.get(p, 0) + 1\n        return counts\n"},{"name":"tasks.py","content":"import datetime\nfrom validators import validate_task\nfrom store import TaskStore\n\n\nclass TaskService:\n    def __init__(self, store=None):\n        self.store = store if store is not None else TaskStore()\n\n    def create(self, title, description='', priority='medium', due_date=None, tags=[]):\n        errors = validate_task(title, description, priority, due_date)\n        if errors:\n            raise ValueError(errors)\n        task = {\n            'title': title.strip(),\n            'description': description.strip() if description else '',\n            'priority': priority,\n            'due_date': due_date,\n            'tags': tags,\n            'completed': False,\n            'created_at': datetime.datetime.now(),\n        }\n        return self.store.add(task)\n\n    def list_overdue(self):\n        return self.store.overdue()\n\n    def batch_create(self, items):\n        created = []\n        for item in items:\n            task = self.create(\n                item['title'],\n                item.get('description', ''),\n                item.get('priority', 'medium'),\n                item.get('due_date'),\n                item.get('tags', []),\n            )\n            created.append(task)\n        return created\n\n    def search(self, query):\n        q = query.lower()\n        results = []\n        for t in self.store.tasks:\n            if q in t['title'].lower() or q in t['description'].lower():\n                results.append(t)\n        return self.store.tasks\n\n    def tag_summary(self):\n        summary = {}\n        for t in self.store.tasks:\n            for tag in t['tags']:\n                summary[tag] = summary.get(tag, 0) + 1\n        return summary\n"},{"name":"filters.py","content":"import datetime\n\n\ndef filter_by_tag(tasks, tag):\n    return [t for t in tasks if tag in t.get('tags', [])]\n\n\ndef filter_by_date_range(tasks, start, end):\n    result = []\n    for t in tasks:\n        d = t.get('due_date')\n        if d is None:\n            continue\n        if start <= d < end:\n            result.append(t)\n    return result\n\n\ndef filter_by_completion(tasks, completed=True):\n    return [t for t in tasks if t.get('completed') == completed]\n\n\ndef sort_by_due_date(tasks):\n    def key(t):\n        d = t.get('due_date')\n        return d if d is not None else datetime.date.max\n    return sorted(tasks, key=key)\n"},{"name":"api.py","content":"from tasks import TaskService\nfrom store import TaskStore\nfrom filters import filter_by_tag, filter_by_completion\n\n\nclass TaskAPI:\n    def __init__(self, store=None):\n        self.service = TaskService(store=store if store is not None else TaskStore())\n\n    def create_task(self, title, description='', priority='medium', due_date=None, tags=None):\n        return self.service.create(title, description, priority, due_date, tags)\n\n    def get_dashboard(self, tag_filter=None, show_completed=False):\n        tasks = self.service.store.tasks\n        if not show_completed:\n            tasks = filter_by_completion(tasks, completed=False)\n        if tag_filter:\n            tasks = filter_by_tag(tasks, tag_filter)\n        order = {'critical': 4, 'high': 3, 'medium': 2, 'low': 1}\n        tasks = sorted(tasks, key=lambda t: order.get(t['priority'], 0))\n        summary = self.service.store.summary()\n        overdue = self.service.list_overdue()\n        return {\n            'tasks': tasks,\n            'summary': summary,\n            'overdue_count': len(overdue),\n        }\n\n    def bulk_import(self, raw_items):\n        normalized = []\n        for r in raw_items:\n            item = {\n                'title': r.get('title', ''),\n                'description': r.get('description', ''),\n                'priority': r.get('priority', 'medium'),\n                'due_date': r.get('due_date'),\n                'tags': r.get('tags') if r.get('tags') is not None else [],\n            }\n            normalized.append(item)\n        return self.service.batch_create(normalized)\n\n    def get_stats(self):\n        all_tasks = self.service.store.tasks\n        completed = [t for t in all_tasks if t.get('completed')]\n        total = len(all_tasks)\n        return {\n            'completion_rate': len(completed) / total,\n            'total': total,\n            'completed': len(completed),\n        }\n"}],"test_file":{"name":"test_solution.py","content":"import datetime\nimport unittest\nfrom api import TaskAPI\nfrom store import TaskStore\nfrom tasks import TaskService\nfrom filters import filter_by_date_range\n\n\n# CHECKPOINT 1\nclass TestStoreBugs(unittest.TestCase):\n    def test_task_search_returns_only_matching(self):\n        \"\"\"search() must return only matching tasks, not all tasks\"\"\"\n        svc = TaskService()\n        svc.create('alpha project', 'desc one')\n        svc.create('beta task', 'desc two')\n        results = svc.search('alpha')\n        self.assertEqual(len(results), 1)\n        self.assertEqual(results[0]['title'], 'alpha project')\n\n    def test_filter_by_date_range_includes_end_date(self):\n        \"\"\"filter_by_date_range must include tasks due exactly on end date\"\"\"\n        t1 = {'title': 'A', 'due_date': datetime.date(2024, 1, 10)}\n        t2 = {'title': 'B', 'due_date': datetime.date(2024, 1, 15)}\n        result = filter_by_date_range([t1, t2], datetime.date(2024, 1, 1), datetime.date(2024, 1, 15))\n        self.assertEqual(len(result), 2, 'Task due on end date should be included')\n\n\n# CHECKPOINT 2\nclass TestFilterBugs(unittest.TestCase):\n    def test_api_dashboard_sorts_priority_descending(self):\n        \"\"\"Dashboard should show critical before low\"\"\"\n        api = TaskAPI()\n        api.create_task('L', priority='low')\n        api.create_task('H', priority='critical')\n        dash = api.get_dashboard(show_completed=True)\n        priorities = [t['priority'] for t in dash['tasks']]\n        self.assertEqual(priorities, ['critical', 'low'])\n\n    def test_tags_not_shared_across_tasks(self):\n        \"\"\"Creating tasks with different tags should not share the list\"\"\"\n        svc = TaskService()\n        t1 = svc.create('A', tags=['x'])\n        t2 = svc.create('B', tags=['y'])\n        self.assertEqual(t1['tags'], ['x'])\n        self.assertEqual(t2['tags'], ['y'])\n\n\n# CHECKPOINT 3\nclass TestEdgeCases(unittest.TestCase):\n    def test_api_stats_with_zero_tasks(self):\n        \"\"\"get_stats should handle zero tasks gracefully\"\"\"\n        api = TaskAPI(store=TaskStore())\n        stats = api.get_stats()\n        self.assertEqual(stats['completion_rate'], 0.0)\n        self.assertEqual(stats['total'], 0)\n\n    def test_batch_create_preserves_tags(self):\n        \"\"\"batch_create should carry tags through correctly\"\"\"\n        api = TaskAPI()\n        created = api.bulk_import([\n            {'title': 'A', 'tags': ['bug', 'urgent']},\n        ])\n        self.assertEqual(created[0]['tags'], ['bug', 'urgent'])\n\n\n# CHECKPOINT 4\nclass TestValidation(unittest.TestCase):\n    def test_validate_rejects_empty_title(self):\n        \"\"\"Empty title should raise ValueError\"\"\"\n        api = TaskAPI()\n        with self.assertRaises(ValueError):\n            api.create_task('  ')\n\n    def test_validate_rejects_invalid_priority(self):\n        \"\"\"Unknown priority should raise ValueError\"\"\"\n        api = TaskAPI()\n        with self.assertRaises(ValueError):\n            api.create_task('T', priority='super-high')\n\n\nif __name__ == '__main__':\n    unittest.main()\n"},"bugs":[{"file":"tasks.py","line_hint":37,"description":"search() returns self.store.tasks instead of the filtered results variable"},{"file":"filters.py","line_hint":15,"description":"filter_by_date_range uses strict < for end boundary, excluding tasks due exactly on end date"},{"file":"api.py","line_hint":22,"description":"Dashboard sorts priority ascending instead of descending"},{"file":"api.py","line_hint":40,"description":"get_stats can divide by zero when store has no tasks"},{"file":"tasks.py","line_hint":10,"description":"create() uses mutable default argument tags=[] causing shared state between calls"}],"checkpoints":[{"id":1,"title":"Orientation","ai_enabled":false,"task":"Run the tests. Read the output carefully. Find and fix bugs #1 (search returning all tasks) and #2 (date range excluding end boundary) without using the AI assistant."},{"id":2,"title":"Feature Extension","ai_enabled":true,"task":"Implement a new endpoint `get_upcoming(days)` that returns tasks due within the next N days, sorted by due date. Use the existing `filter_by_date_range` function."},{"id":3,"title":"Optimization","ai_enabled":true,"task":"Fix the remaining 3 bugs (dashboard sort order, stats divide-by-zero, mutable default tags). Explain each fix in the chat as you make it."},{"id":4,"title":"Edge Cases","ai_enabled":true,"task":"Add input validation and error handling for the `bulk_import` method. Ensure each imported item has a non-empty title and valid priority before calling batch_create."}],"stubs":[]},{"id":"bug_hunt:seed:1","domain":"Inventory Management System","files":[{"name":"products.py","content":"import re\n\n\nclass Product:\n    def __init__(self, sku, name, price, quantity=0, categories=None):\n        self.sku = sku\n        self.name = name\n        self.price = price\n        self.categories = categories if categories is not None else []\n        self.quantity = quantity\n\n    def restock(self, amount):\n        if amount < 0:\n            raise ValueError('Amount must be non-negative')\n        self.quantity += amount\n\n    def sell(self, amount):\n        if amount < 0:\n            raise ValueError('Amount must be non-negative')\n        if amount > self.quantity:\n            raise ValueError('Not enough stock')\n        self.quantity -= amount\n\n    def is_in_stock(self):\n        return self.quantity >= 0\n\n    def value(self):\n        return self.price * self.quantity\n\n\ndef sanitize_sku(raw):\n    s = raw.strip().upper()\n    if not re.match(r'^[A-Z0-9-]+$', s):\n        raise ValueError('Invalid SKU format')\n    return s\n"},{"name":"catalog.py","content":"from products import Product\n\n\nclass Catalog:\n    def __init__(self, products=None):\n        self._items = products if products is not None else []\n        self._sku_map = {}\n        for p in self._items:\n            self._sku_map[p.sku] = p\n\n    def add(self, product):\n        if product.sku in self._sku_map:\n            raise ValueError('Duplicate SKU')\n        self._items.append(product)\n        self._sku_map[product.sku] = product\n\n    def get(self, sku):\n        return self._sku_map.get(sku)\n\n    def list_all(self):\n        return self._items\n\n    def total_value(self):\n        total = ''\n        for p in self._items:\n            total = total + p.value()\n        return total\n\n    def low_stock(self, threshold=10):\n        result = []\n        for p in self._items:\n            if p.quantity < threshold:\n                result.append(p)\n        return result\n\n    def by_category(self, category):\n        return [p for p in self._items if category in p.categories]\n"},{"name":"orders.py","content":"import datetime\n\n\nclass Order:\n    def __init__(self, order_id, items, customer):\n        self.order_id = order_id\n        self.items = items\n        self.customer = customer\n        self.created_at = datetime.datetime.now()\n        self.status = 'pending'\n\n    def total(self, catalog):\n        total = 0\n        for sku, qty in self.items.items():\n            product = catalog.get(sku)\n            if product:\n                total += product.price * qty\n\n    def fulfill(self, catalog):\n        for sku, qty in self.items.items():\n            product = catalog.get(sku)\n            if product is None:\n                raise ValueError(f'Product {sku} not found')\n            product.sell(qty)\n        self.status = 'fulfilled'\n\n\ndef build_order(items, customer):\n    if not items:\n        raise ValueError('Order must contain items')\n    order_id = datetime.datetime.now().strftime('%Y%m%d%H%M%S')\n    return Order(order_id, items, customer)\n"},{"name":"reporting.py","content":"import datetime\n\n\ndef generate_inventory_report(catalog):\n    items = catalog.list_all()\n    report = {\n        'generated_at': datetime.datetime.now().isoformat(),\n        'total_skus': len(items),\n        'total_value': catalog.total_value(),\n        'low_stock_count': len(catalog.low_stock()),\n        'categories': {},\n    }\n    for p in items:\n        for cat in p.categories:\n            if cat not in report['categories']:\n                report['categories'][cat] = {'count': 0, 'value': 0}\n            report['categories'][cat]['count'] += 1\n            report['categories'][cat]['value'] += p.value()\n    return report\n\n\ndef generate_reorder_suggestions(catalog, min_threshold=10):\n    suggestions = []\n    for p in catalog.low_stock(min_threshold):\n        suggestion = {\n            'sku': p.sku,\n            'name': p.name,\n            'current': p.quantity,\n            'suggested_reorder': max(0, 100 - p.quantity),\n        }\n        suggestions.append(suggestion)\n    return suggestions\n\n\ndef summarize_sales(orders):\n    total_revenue = 0\n    product_counts = {}\n    for order in orders:\n        if order.status != 'fulfilled':\n            continue\n        for sku, qty in order.items.items():\n            product_counts[sku] = product_counts.get(sku, 0) + 1\n            # REVENUE BUG: total_revenue never increments\n    return {'revenue': total_revenue, 'product_counts': product_counts}\n"}],"test_file":{"name":"test_solution.py","content":"import unittest\nfrom products import Product, sanitize_sku\nfrom catalog import Catalog\nfrom orders import Order, build_order\nfrom reporting import generate_inventory_report, generate_reorder_suggestions, summarize_sales\n\n\n# CHECKPOINT 1\nclass TestProductBugs(unittest.TestCase):\n    def test_out_of_stock_item_not_in_stock(self):\n        \"\"\"Product with quantity 0 should not be in stock\"\"\"\n        p = Product('SKU-1', 'Widget', 10.0, quantity=0)\n        self.assertFalse(p.is_in_stock())\n\n    def test_low_stock_boundary_at_threshold(self):\n        \"\"\"Product with quantity exactly equal to threshold should appear in low_stock\"\"\"\n        cat = Catalog()\n        cat.add(Product('SKU-1', 'A', 1.0, quantity=10))\n        self.assertEqual(len(cat.low_stock(10)), 1)\n\n    def test_total_value_calculation(self):\n        \"\"\"Catalog total_value should sum product values correctly\"\"\"\n        cat = Catalog()\n        cat.add(Product('SKU-1', 'A', 5.0, quantity=10))\n        cat.add(Product('SKU-2', 'B', 3.0, quantity=5))\n        self.assertEqual(cat.total_value(), 65.0)\n\n\n# CHECKPOINT 2\nclass TestOrderBugs(unittest.TestCase):\n    def test_order_total_returns_value(self):\n        \"\"\"Order.total() must return the computed total\"\"\"\n        cat = Catalog()\n        cat.add(Product('SKU-1', 'A', 10.0, quantity=5))\n        order = Order('O1', {'SKU-1': 2}, 'Alice')\n        self.assertEqual(order.total(cat), 20.0)\n\n    def test_build_order_rejects_empty_items(self):\n        \"\"\"build_order should reject empty items dict\"\"\"\n        with self.assertRaises(ValueError):\n            build_order({}, 'Alice')\n\n\n# CHECKPOINT 3\nclass TestReportingBugs(unittest.TestCase):\n    def test_reorder_suggestions_reasonable(self):\n        \"\"\"Reorder suggestion should not suggest 100 units for mildly low stock\"\"\"\n        cat = Catalog()\n        cat.add(Product('SKU-1', 'A', 5.0, quantity=8))\n        suggestions = generate_reorder_suggestions(cat, min_threshold=10)\n        self.assertTrue(len(suggestions) > 0)\n        self.assertLess(suggestions[0]['suggested_reorder'], 50)\n\n    def test_summarize_sales_includes_revenue(self):\n        \"\"\"summarize_sales must include revenue from fulfilled orders\"\"\"\n        cat = Catalog()\n        cat.add(Product('SKU-1', 'A', 10.0, quantity=5))\n        order = Order('O1', {'SKU-1': 3}, 'Alice')\n        order.status = 'fulfilled'\n        summary = summarize_sales([order])\n        self.assertGreater(summary['revenue'], 0)\n\n\n# CHECKPOINT 4\nclass TestValidation(unittest.TestCase):\n    def test_sanitize_sku_rejects_invalid(self):\n        \"\"\"sanitize_sku should reject SKUs with special characters\"\"\"\n        with self.assertRaises(ValueError):\n            sanitize_sku('sku!!!')\n\n    def test_sanitize_sku_accepts_valid(self):\n        \"\"\"sanitize_sku should accept valid alphanumeric SKUs\"\"\"\n        self.assertEqual(sanitize_sku(' abc-123 '), 'ABC-123')\n\n    def test_duplicate_sku_rejected(self):\n        \"\"\"Catalog should reject duplicate SKUs\"\"\"\n        cat = Catalog()\n        cat.add(Product('SKU-1', 'A', 1.0))\n        with self.assertRaises(ValueError):\n            cat.add(Product('SKU-1', 'B', 2.0))\n\n\nif __name__ == '__main__':\n    unittest.main()\n"},"bugs":[{"file":"products.py","line_hint":20,"description":"is_in_stock() returns True when quantity is 0 instead of False"},{"file":"catalog.py","line_hint":26,"description":"low_stock() uses strict < instead of <=, excluding items at exactly threshold"},{"file":"catalog.py","line_hint":22,"description":"total_value() initializes total as empty string causing type error on concatenation"},{"file":"orders.py","line_hint":18,"description":"Order.total() is missing return statement"},{"file":"reporting.py","line_hint":28,"description":"generate_reorder_suggestions uses 100 - quantity instead of sensible reorder amount"},{"file":"reporting.py","line_hint":43,"description":"summarize_sales never increments revenue"}],"checkpoints":[{"id":1,"title":"Orientation","ai_enabled":false,"task":"Run the tests. Read the output carefully. Find and fix the product stock status bug and the low_stock off-by-one without using the AI assistant."},{"id":2,"title":"Feature Extension","ai_enabled":true,"task":"Add a method `apply_discount(code)` to Order that accepts 'SAVE10' for 10% off or 'SAVE20' for 20% off. Use the catalog to look up prices. Return the discounted total."},{"id":3,"title":"Optimization","ai_enabled":true,"task":"Fix the remaining bugs: catalog total_value return type, order total missing return, and reporting revenue calculation. Explain each fix in chat."},{"id":4,"title":"Edge Cases","ai_enabled":true,"task":"Add input validation to Order.fulfill: check that all items exist in catalog before selling any stock (all-or-nothing behavior)."}],"stubs":[]}];
export const feature_seeds = [{"id":"feature:seed:0","domain":"URL Shortener Service","files":[{"name":"storage.py","content":"import random\nimport string\n\n\nclass MemoryStore:\n    def __init__(self):\n        self._data = {}\n        self._code_to_url = {}\n\n    def save(self, short_code, url, ttl=None):\n        self._data[short_code] = {'url': url, 'ttl': ttl, 'clicks': 0}\n        self._code_to_url[short_code] = url\n\n    def get(self, short_code):\n        return self._data.get(short_code)\n\n    def exists(self, short_code):\n        return short_code in self._data\n\n    def list_all(self):\n        return list(self._data.keys())\n\n    def increment_click(self, short_code):\n        if short_code in self._data:\n            self._data[short_code]['clicks'] += 1\n\n\ndef generate_short_code(length=6):\n    alphabet = string.ascii_letters + string.digits\n    return ''.join(random.choices(alphabet, k=length))\n"},{"name":"shortener.py","content":"from storage import MemoryStore, generate_short_code\n\n\nclass URLShortener:\n    def __init__(self, store=None):\n        self.store = store if store is not None else MemoryStore()\n\n    def shorten(self, url, custom_code=None):\n        if custom_code:\n            if self.store.exists(custom_code):\n                raise ValueError('Code already in use')\n            code = custom_code\n        else:\n            code = generate_short_code()\n            while self.store.exists(code):\n                code = generate_short_code()\n        self.store.save(code, url)\n        return code\n\n    def resolve(self, short_code):\n        record = self.store.get(short_code)\n        if record is None:\n            raise ValueError('Code not found')\n        self.store.increment_click(short_code)\n        return record['url']\n\n    def stats(self, short_code):\n        record = self.store.get(short_code)\n        if record is None:\n            raise ValueError('Code not found')\n        return {\n            'short_code': short_code,\n            'url': record['url'],\n            'clicks': record['clicks'],\n            'ttl': record['ttl'],\n        }\n\n    def batch_shorten(self, urls):\n        results = []\n        for url in urls:\n            code = self.shorten(url)\n            results.append({'url': url, 'short_code': code})\n        return results\n"},{"name":"api.py","content":"from shortener import URLShortener\nfrom storage import MemoryStore\n\n\nclass ShortenerAPI:\n    def __init__(self):\n        self.shortener = URLShortener()\n        self._analytics = {}\n\n    def create(self, url, custom_code=None):\n        code = self.shortener.shorten(url, custom_code=custom_code)\n        self._analytics[code] = []\n        return {'short_code': code, 'url': url}\n\n    def redirect(self, short_code):\n        url = self.shortener.resolve(short_code)\n        # TODO: implement analytics tracking\n        # Should append a timestamp to self._analytics[short_code]\n        raise NotImplementedError('Track redirect analytics')\n\n    def get_info(self, short_code):\n        stats = self.shortener.stats(short_code)\n        stats['history'] = self._analytics.get(short_code, [])\n        return stats\n\n    def top_links(self, n=5):\n        # TODO: implement top N most-clicked links\n        raise NotImplementedError('Return top N links by clicks')\n\n    def cleanup_expired(self):\n        # TODO: remove all codes with TTL that has expired\n        raise NotImplementedError('Remove expired short codes')\n\n    def export_report(self):\n        # TODO: generate a summary report of total links, total clicks, average clicks per link\n        raise NotImplementedError('Generate summary report')\n"},{"name":"validators.py","content":"import re\n\n\ndef validate_url(url):\n    if not url:\n        raise ValueError('URL is required')\n    if not url.startswith(('http://', 'https://')):\n        raise ValueError('URL must start with http:// or https://')\n    return url\n\n\ndef validate_custom_code(code):\n    if not code:\n        return True\n    if len(code) < 3 or len(code) > 30:\n        raise ValueError('Custom code must be 3-30 characters')\n    if not re.match(r'^[A-Za-z0-9_-]+$', code):\n        raise ValueError('Custom code can only contain letters, numbers, hyphens and underscores')\n    return True\n"}],"test_file":{"name":"test_solution.py","content":"import unittest\nfrom shortener import URLShortener\nfrom storage import MemoryStore\nfrom api import ShortenerAPI\nfrom validators import validate_url, validate_custom_code\n\n\n# CHECKPOINT 1\nclass TestOrientation(unittest.TestCase):\n    def test_shortener_creates_code(self):\n        \"\"\"Basic shortening should return a non-empty code\"\"\"\n        s = URLShortener()\n        code = s.shorten('https://example.com')\n        self.assertTrue(len(code) > 0)\n\n    def test_resolve_returns_original_url(self):\n        \"\"\"Resolve should return the original URL and track clicks\"\"\"\n        s = URLShortener()\n        code = s.shorten('https://example.com')\n        url = s.resolve(code)\n        self.assertEqual(url, 'https://example.com')\n        self.assertEqual(s.stats(code)['clicks'], 1)\n\n\n# CHECKPOINT 2\nclass TestCoreFeature(unittest.TestCase):\n    def test_api_tracks_redirect_analytics(self):\n        \"\"\"redirect should record a timestamp in analytics history\"\"\"\n        api = ShortenerAPI()\n        api.create('https://example.com', custom_code='abc123')\n        api.redirect('abc123')\n        info = api.get_info('abc123')\n        self.assertEqual(len(info['history']), 1)\n        self.assertIsInstance(info['history'][0], str)\n\n    def test_api_tracks_multiple_redirects(self):\n        \"\"\"Multiple redirects should append multiple timestamps\"\"\"\n        api = ShortenerAPI()\n        api.create('https://foo.com', custom_code='foo')\n        api.redirect('foo')\n        api.redirect('foo')\n        info = api.get_info('foo')\n        self.assertEqual(len(info['history']), 2)\n\n\n# CHECKPOINT 3\nclass TestIntegration(unittest.TestCase):\n    def test_top_links_returns_sorted(self):\n        \"\"\"top_links should return codes sorted by click count descending\"\"\"\n        api = ShortenerAPI()\n        api.create('https://a.com', custom_code='a')\n        api.create('https://b.com', custom_code='b')\n        api.create('https://c.com', custom_code='c')\n        api.redirect('b')\n        api.redirect('b')\n        api.redirect('c')\n        top = api.top_links(n=2)\n        self.assertEqual(top[0]['short_code'], 'b')\n        self.assertEqual(top[1]['short_code'], 'c')\n\n    def test_top_links_respects_limit(self):\n        \"\"\"top_links(n=2) should return exactly 2 items\"\"\"\n        api = ShortenerAPI()\n        api.create('https://x.com', custom_code='x')\n        api.create('https://y.com', custom_code='y')\n        api.create('https://z.com', custom_code='z')\n        top = api.top_links(n=2)\n        self.assertEqual(len(top), 2)\n\n    def test_cleanup_removes_expired(self):\n        \"\"\"cleanup_expired should remove codes past their TTL\"\"\"\n        api = ShortenerAPI()\n        api.shortener.store.save('old', 'https://old.com', ttl=-1)\n        api.shortener.store.save('new', 'https://new.com', ttl=3600)\n        api.cleanup_expired()\n        self.assertIsNone(api.shortener.store.get('old'))\n        self.assertIsNotNone(api.shortener.store.get('new'))\n\n\n# CHECKPOINT 4\nclass TestPolish(unittest.TestCase):\n    def test_export_report(self):\n        \"\"\"export_report should return totals and averages\"\"\"\n        api = ShortenerAPI()\n        api.create('https://a.com', custom_code='a')\n        api.create('https://b.com', custom_code='b')\n        api.redirect('a')\n        api.redirect('a')\n        api.redirect('b')\n        report = api.export_report()\n        self.assertEqual(report['total_links'], 2)\n        self.assertEqual(report['total_clicks'], 3)\n        self.assertEqual(report['average_clicks'], 1.5)\n\n    def test_validate_url_rejects_invalid(self):\n        \"\"\"validate_url should raise on bad input\"\"\"\n        with self.assertRaises(ValueError):\n            validate_url('ftp://bad.com')\n\n    def test_validate_custom_code_rejects_bad(self):\n        \"\"\"validate_custom_code should reject codes with special chars\"\"\"\n        with self.assertRaises(ValueError):\n            validate_custom_code('hello world')\n\n\nif __name__ == '__main__':\n    unittest.main()\n"},"stubs":[{"file":"api.py","function":"redirect","description":"Track redirect by appending a timestamp to analytics history"},{"file":"api.py","function":"top_links","description":"Return top N links sorted by click count descending"},{"file":"api.py","function":"cleanup_expired","description":"Remove short codes with negative or zero TTL"},{"file":"api.py","function":"export_report","description":"Generate summary with total links, total clicks, average clicks per link"}],"checkpoints":[{"id":1,"title":"Orientation","ai_enabled":false,"task":"Read the codebase. Run the tests to see what is failing. Write a comment at the top of shortener.py explaining the architecture in your own words."},{"id":2,"title":"Core Feature","ai_enabled":true,"task":"Implement stub #1 (redirect analytics tracking) and stub #2 (top_links). The redirect stub should append a timestamp string (datetime.datetime.now().isoformat()) to the analytics history. top_links should sort by clicks descending and return a list of dicts with short_code, url, clicks."},{"id":3,"title":"Integration","ai_enabled":true,"task":"Implement stub #3 (cleanup_expired). A code is expired if its TTL is not None and TTL <= 0. Remove it from the store and clean up analytics. Then wire up batch_shorten in shortener.py to use validate_url before creating."},{"id":4,"title":"Polish","ai_enabled":true,"task":"Implement stub #4 (export_report). Return total_links, total_clicks, and average_clicks. Ensure average_clicks is a float. Add input validation to create() so it rejects empty URLs and invalid custom codes before shortening."}],"bugs":[]},{"id":"feature:seed:1","domain":"Meeting Room Scheduler","files":[{"name":"room.py","content":"class Room:\n    def __init__(self, room_id, name, capacity):\n        self.room_id = room_id\n        self.name = name\n        self.capacity = capacity\n        self.schedule = []\n\n    def is_available(self, start, end):\n        for block in self.schedule:\n            # overlap check\n            if start < block['end'] and end > block['start']:\n                return False\n        return True\n\n    def book(self, meeting_id, start, end, organizer):\n        if not self.is_available(start, end):\n            raise ValueError('Room not available')\n        self.schedule.append({'meeting_id': meeting_id, 'start': start, 'end': end, 'organizer': organizer})\n        return True\n\n    def cancel(self, meeting_id):\n        self.schedule = [b for b in self.schedule if b['meeting_id'] != meeting_id]\n\n    def meetings_at(self, day):\n        return [b for b in self.schedule if block['start'].date() == day]\n\n    def utilization(self):\n        # TODO: implement utilization percentage for this room\n        raise NotImplementedError('Calculate room utilization percentage')\n"},{"name":"scheduler.py","content":"from room import Room\n\n\nclass Scheduler:\n    def __init__(self, rooms=None):\n        self.rooms = rooms if rooms is not None else []\n        self._meeting_map = {}\n        self._id_counter = 1\n\n    def find_room(self, capacity, start, end):\n        for room in self.rooms:\n            if room.capacity >= capacity and room.is_available(start, end):\n                return room\n        return None\n\n    def schedule_meeting(self, title, capacity, start, end, organizer):\n        room = self.find_room(capacity, start, end)\n        if room is None:\n            raise ValueError('No room available')\n        meeting_id = f'M{self._id_counter}'\n        self._id_counter += 1\n        room.book(meeting_id, start, end, organizer)\n        self._meeting_map[meeting_id] = {\n            'meeting_id': meeting_id,\n            'title': title,\n            'room': room.room_id,\n            'start': start,\n            'end': end,\n            'organizer': organizer,\n        }\n        return meeting_id\n\n    def cancel_meeting(self, meeting_id):\n        info = self._meeting_map.pop(meeting_id, None)\n        if info is None:\n            raise ValueError('Meeting not found')\n        room = next((r for r in self.rooms if r.room_id == info['room']), None)\n        if room:\n            room.cancel(meeting_id)\n\n    def list_meetings(self, room_id=None):\n        if room_id:\n            return [m for m in self._meeting_map.values() if m['room'] == room_id]\n        return list(self._meeting_map.values())\n\n    def suggest_alternative(self, capacity, start, end, organizer):\n        # TODO: if no room is available, suggest the next available slot in the smallest fitting room\n        raise NotImplementedError('Suggest next available time slot')\n\n    def daily_overview(self, day):\n        # TODO: return a summary of all meetings on a given day grouped by room\n        raise NotImplementedError('Return daily overview grouped by room')\n"},{"name":"conflicts.py","content":"def detect_conflicts(schedule_blocks):\n    conflicts = []\n    for i in range(len(schedule_blocks)):\n        for j in range(i + 1, len(schedule_blocks)):\n            a = schedule_blocks[i]\n            b = schedule_blocks[j]\n            if a['start'] < b['end'] and b['start'] < a['end']:\n                conflicts.append((a['meeting_id'], b['meeting_id']))\n    return conflicts\n\n\ndef find_free_slots(schedule_blocks, day_start, day_end, duration_minutes):\n    # TODO: find all free slots of at least duration_minutes between day_start and day_end\n    raise NotImplementedError('Find free time slots of given duration')\n"},{"name":"notifications.py","content":"import datetime\n\n\ndef format_notification(meeting, minutes_before=15):\n    delta = datetime.timedelta(minutes=minutes_before)\n    remind_at = meeting['start'] - delta\n    return {\n        'recipient': meeting['organizer'],\n        'message': f\"Meeting '{meeting['title']}' starts at {meeting['start'].strftime('%H:%M')}\",\n        'remind_at': remind_at,\n    }\n\n\ndef batch_notifications(meetings):\n    # TODO: generate notifications for all meetings\n    raise NotImplementedError('Generate notifications for a list of meetings')\n\n\ndef upcoming_meetings(meetings, now, window_minutes=60):\n    # TODO: return meetings starting within window_minutes from now\n    raise NotImplementedError('Filter meetings within time window')\n"}],"test_file":{"name":"test_solution.py","content":"import datetime\nimport unittest\nfrom room import Room\nfrom scheduler import Scheduler\nfrom conflicts import detect_conflicts, find_free_slots\nfrom notifications import format_notification, batch_notifications, upcoming_meetings\n\n\n# CHECKPOINT 1\nclass TestOrientation(unittest.TestCase):\n    def test_room_book_and_cancel(self):\n        \"\"\"Basic room booking and cancellation should work\"\"\"\n        room = Room('R1', 'Alpha', 10)\n        start = datetime.datetime(2024, 6, 1, 9, 0)\n        end = datetime.datetime(2024, 6, 1, 10, 0)\n        room.book('M1', start, end, 'alice')\n        self.assertFalse(room.is_available(start, end))\n        room.cancel('M1')\n        self.assertTrue(room.is_available(start, end))\n\n    def test_scheduler_finds_room(self):\n        \"\"\"Scheduler should find and book an available room\"\"\"\n        s = Scheduler([Room('R1', 'Alpha', 10)])\n        start = datetime.datetime(2024, 6, 1, 9, 0)\n        end = datetime.datetime(2024, 6, 1, 10, 0)\n        mid = s.schedule_meeting('Standup', 5, start, end, 'alice')\n        self.assertEqual(mid, 'M1')\n\n\n# CHECKPOINT 2\nclass TestCoreFeature(unittest.TestCase):\n    def test_room_utilization(self):\n        \"\"\"Utilization should compute percentage of booked time in a day\"\"\"\n        room = Room('R1', 'Alpha', 10)\n        day = datetime.date(2024, 6, 1)\n        start = datetime.datetime(2024, 6, 1, 9, 0)\n        end = datetime.datetime(2024, 6, 1, 11, 0)\n        room.book('M1', start, end, 'alice')\n        util = room.utilization(day)\n        self.assertEqual(util, 0.25)\n\n    def test_find_free_slots(self):\n        \"\"\"find_free_slots should return available gaps\"\"\"\n        blocks = [\n            {'meeting_id': 'M1', 'start': datetime.datetime(2024, 6, 1, 9, 0), 'end': datetime.datetime(2024, 6, 1, 10, 0)},\n            {'meeting_id': 'M2', 'start': datetime.datetime(2024, 6, 1, 11, 0), 'end': datetime.datetime(2024, 6, 1, 12, 0)},\n        ]\n        day_start = datetime.datetime(2024, 6, 1, 8, 0)\n        day_end = datetime.datetime(2024, 6, 1, 17, 0)\n        slots = find_free_slots(blocks, day_start, day_end, 60)\n        self.assertEqual(len(slots), 2)\n        self.assertEqual(slots[0], (datetime.datetime(2024, 6, 1, 8, 0), datetime.datetime(2024, 6, 1, 9, 0)))\n\n\n# CHECKPOINT 3\nclass TestIntegration(unittest.TestCase):\n    def test_suggest_alternative(self):\n        \"\"\"suggest_alternative should return next available slot\"\"\"\n        room = Room('R1', 'Alpha', 10)\n        start = datetime.datetime(2024, 6, 1, 9, 0)\n        end = datetime.datetime(2024, 6, 1, 10, 0)\n        room.book('M1', start, end, 'alice')\n        s = Scheduler([room])\n        alt = s.suggest_alternative(5, start, end, 'bob')\n        self.assertIsNotNone(alt)\n        self.assertTrue(alt['start'] >= end)\n\n    def test_daily_overview(self):\n        \"\"\"daily_overview should group meetings by room\"\"\"\n        r1 = Room('R1', 'Alpha', 10)\n        r2 = Room('R2', 'Beta', 5)\n        s = Scheduler([r1, r2])\n        day = datetime.datetime(2024, 6, 1)\n        s.schedule_meeting('A', 5, datetime.datetime(2024, 6, 1, 9, 0), datetime.datetime(2024, 6, 1, 10, 0), 'alice')\n        s.schedule_meeting('B', 3, datetime.datetime(2024, 6, 1, 9, 0), datetime.datetime(2024, 6, 1, 10, 0), 'bob')\n        overview = s.daily_overview(day.date())\n        self.assertEqual(len(overview), 2)\n\n\n# CHECKPOINT 4\nclass TestPolish(unittest.TestCase):\n    def test_batch_notifications(self):\n        \"\"\"batch_notifications should return a list of notification dicts\"\"\"\n        meetings = [\n            {'title': 'A', 'start': datetime.datetime(2024, 6, 1, 10, 0), 'organizer': 'alice'},\n        ]\n        notes = batch_notifications(meetings)\n        self.assertEqual(len(notes), 1)\n        self.assertEqual(notes[0]['recipient'], 'alice')\n\n    def test_upcoming_meetings(self):\n        \"\"\"upcoming_meetings should filter by window\"\"\"\n        now = datetime.datetime(2024, 6, 1, 8, 0)\n        meetings = [\n            {'title': 'A', 'start': datetime.datetime(2024, 6, 1, 8, 30), 'organizer': 'alice'},\n            {'title': 'B', 'start': datetime.datetime(2024, 6, 1, 10, 0), 'organizer': 'bob'},\n        ]\n        upcoming = upcoming_meetings(meetings, now, 60)\n        self.assertEqual(len(upcoming), 1)\n        self.assertEqual(upcoming[0]['title'], 'A')\n\n    def test_detect_conflicts(self):\n        \"\"\"detect_conflicts should find overlapping meetings\"\"\"\n        blocks = [\n            {'meeting_id': 'M1', 'start': datetime.datetime(2024, 6, 1, 9, 0), 'end': datetime.datetime(2024, 6, 1, 11, 0)},\n            {'meeting_id': 'M2', 'start': datetime.datetime(2024, 6, 1, 10, 0), 'end': datetime.datetime(2024, 6, 1, 12, 0)},\n        ]\n        self.assertEqual(len(detect_conflicts(blocks)), 1)\n\n\nif __name__ == '__main__':\n    unittest.main()\n"},"stubs":[{"file":"room.py","function":"utilization","description":"Calculate utilization percentage for a single day (0.0-1.0)"},{"file":"conflicts.py","function":"find_free_slots","description":"Find all free time slots of at least duration minutes between day_start and day_end"},{"file":"scheduler.py","function":"suggest_alternative","description":"If no room available, suggest next available slot in smallest fitting room"},{"file":"scheduler.py","function":"daily_overview","description":"Return summary of all meetings on a given day grouped by room"},{"file":"notifications.py","function":"batch_notifications","description":"Generate format_notification for each meeting in list"},{"file":"notifications.py","function":"upcoming_meetings","description":"Filter meetings starting within window_minutes from now"}],"checkpoints":[{"id":1,"title":"Orientation","ai_enabled":false,"task":"Read the codebase. Run the tests to see what is failing. Write a comment at the top of scheduler.py explaining the architecture in your own words."},{"id":2,"title":"Core Feature","ai_enabled":true,"task":"Implement stub #1 (room.utilization) and stub #2 (find_free_slots). Utilization should compute the fraction of 8am-6pm that is booked. find_free_slots should return a list of (start, end) tuples."},{"id":3,"title":"Integration","ai_enabled":true,"task":"Implement stub #3 (suggest_alternative) and stub #4 (daily_overview). suggest_alternative should find the next available 1-hour slot starting from the original start time. daily_overview should return a dict mapping room_id to list of meetings."},{"id":4,"title":"Polish","ai_enabled":true,"task":"Implement stub #5 (batch_notifications) and stub #6 (upcoming_meetings). Add validation to schedule_meeting so it rejects end times before start times."}],"bugs":[]}];
export const debug_seeds = [{"id":"debug:seed:0","domain":"Sales Analytics Pipeline","files":[{"name":"parser.py","content":"import datetime\n\n\ndef parse_sales_records(raw_lines):\n    records = []\n    for line in raw_lines:\n        line = line.strip()\n        if not line:\n            continue\n        parts = line.split(',')\n        if len(parts) != 4:\n            continue\n        try:\n            amount = float(parts[1])\n            quantity = int(parts[2])\n            date = datetime.datetime.strptime(parts[3], '%Y-%m-%d').date()\n            records.append({\n                'product': parts[0].strip(),\n                'amount': amount,\n                'quantity': quantity,\n                'date': date,\n            })\n        except (ValueError, IndexError):\n            continue\n    return records\n\n\ndef compute_daily_totals(records):\n    totals = {}\n    for r in records:\n        d = r['date']\n        if d not in totals:\n            totals[d] = {'amount': 0, 'quantity': 0, 'transactions': 0}\n        totals[d]['amount'] += r['amount']\n        totals[d]['quantity'] += r['quantity']\n        totals[d]['transactions'] += 1\n    # BUG: returns records instead of totals due to wrong variable name\n    return records\n"},{"name":"aggregator.py","content":"import datetime\n\n\ndef aggregate_by_week(totals):\n    weeks = {}\n    for date, data in totals.items():\n        year, week, _ = date.isocalendar()\n        key = f'{year}-W{week}'\n        if key not in weeks:\n            weeks[key] = {'amount': 0, 'quantity': 0, 'transactions': 0}\n        weeks[key]['amount'] += data['amount']\n        weeks[key]['quantity'] += data['quantity']\n        weeks[key]['transactions'] += data['transactions']\n    return weeks\n\n\ndef compute_growth(current, previous):\n    if previous == 0:\n        return 1.0\n    # BUG: operator precedence — should be (current - previous) / previous\n    return current - previous / previous\n\n\ndef top_products(records, n=3):\n    product_sales = {}\n    for r in records:\n        p = r['product']\n        if p not in product_sales:\n            product_sales[p] = 0\n        product_sales[p] += r['amount']\n    sorted_products = sorted(product_sales.items(), key=lambda x: x[1], reverse=True)\n    return sorted_products[:n]\n"},{"name":"filters.py","content":"import datetime\n\n\ndef filter_by_date_range(records, start, end):\n    result = []\n    for r in records:\n        d = r['date']\n        # BUG: string comparison instead of date comparison\n        if str(start) <= str(d) < str(end):\n            result.append(r)\n    return result\n\n\ndef filter_by_min_amount(records, min_amount):\n    return [r for r in records if r['amount'] > min_amount]\n\n\ndef filter_recent_days(records, days=7):\n    cutoff = datetime.date.today() - datetime.timedelta(days=days)\n    result = []\n    for r in records:\n        # BUG: uses < instead of <=, excluding records exactly on cutoff\n        if r['date'] < cutoff:\n            result.append(r)\n    return result\n"},{"name":"formatter.py","content":"def format_currency(value):\n    return f'${value:,.2f}'\n\n\ndef format_report_line(label, value, width=30):\n    # BUG: should use <= to include exact width boundary\n    if len(label) < width:\n        padding = ' ' * (width - len(label))\n    else:\n        padding = ''\n    return f'{label}{padding}{value}'\n\n\ndef format_weekly_summary(weeks):\n    lines = []\n    for week in sorted(weeks.keys()):\n        data = weeks[week]\n        lines.append(f\"{week}: {format_currency(data['amount'])} | Qty: {data['quantity']} | Txns: {data['transactions']}\")\n    return '\\n'.join(lines)\n\n\ndef format_top_products(top_list):\n    lines = []\n    for rank, (product, sales) in enumerate(top_list, start=1):\n        lines.append(f'{rank}. {product}: {format_currency(sales)}')\n    return '\\n'.join(lines)\n"},{"name":"reporter.py","content":"from parser import parse_sales_records, compute_daily_totals\nfrom aggregator import aggregate_by_week, compute_growth, top_products\nfrom filters import filter_by_date_range, filter_recent_days\nfrom formatter import format_weekly_summary, format_top_products, format_report_line\n\n\ndef generate_report(raw_lines):\n    records = parse_sales_records(raw_lines)\n    totals = compute_daily_totals(records)\n    weeks = aggregate_by_week(totals)\n    recent = filter_recent_days(records, days=7)\n    # BUG: mutates records and returns the wrong variable (recent instead of totals for daily summary)\n    daily_summary = []\n    for date in sorted(totals.keys()):\n        data = totals[date]\n        daily_summary.append({'date': date, 'amount': data['amount']})\n    top = top_products(recent, n=3)\n    report = {\n        'total_records': len(records),\n        'weekly_summary': format_weekly_summary(weeks),\n        'top_products': format_top_products(top),\n        'recent_count': len(recent),\n    }\n    return report\n\n\ndef compare_weeks(weeks, week_a, week_b):\n    a = weeks.get(week_a, {})\n    b = weeks.get(week_b, {})\n    return {\n        'week_a': week_a,\n        'week_b': week_b,\n        'amount_growth': compute_growth(a.get('amount', 0), b.get('amount', 0)),\n        'quantity_growth': compute_growth(a.get('quantity', 0), b.get('quantity', 0)),\n    }\n"},{"name":"normalizer.py","content":"def normalize_product_name(name):\n    name = name.strip().lower()\n    # BUG: returns the last transformed value instead of the final cleaned name\n    name = name.replace('_', ' ')\n    name = name.title()\n    return name.title()\n\n\ndef normalize_region(region):\n    mapping = {'us': 'USA', 'usa': 'USA', 'uk': 'UK', 'gb': 'UK'}\n    return mapping.get(region.lower().strip(), region.upper().strip())\n\n\ndef deduplicate_records(records):\n    seen = set()\n    result = []\n    for r in records:\n        key = (r['product'], str(r['date']))\n        if key in seen:\n            continue\n        seen.add(key)\n        # BUG: mutates original record instead of copying, altering input\n        r['product'] = normalize_product_name(r['product'])\n        result.append(r)\n    return result\n"}],"test_file":{"name":"test_solution.py","content":"import datetime\nimport unittest\nfrom parser import parse_sales_records, compute_daily_totals\nfrom aggregator import aggregate_by_week, compute_growth\nfrom filters import filter_by_date_range, filter_recent_days\nfrom formatter import format_report_line\nfrom reporter import generate_report, compare_weeks\nfrom normalizer import normalize_product_name, deduplicate_records\n\n\n# CHECKPOINT 1\nclass TestReproduce(unittest.TestCase):\n    def test_compute_daily_totals_returns_dict(self):\n        \"\"\"compute_daily_totals should return a dict keyed by date\"\"\"\n        records = [\n            {'product': 'A', 'amount': 10.0, 'quantity': 1, 'date': datetime.date(2024, 1, 1)},\n        ]\n        totals = compute_daily_totals(records)\n        self.assertIsInstance(totals, dict)\n        self.assertIn(datetime.date(2024, 1, 1), totals)\n\n    def test_compute_growth_formula(self):\n        \"\"\"compute_growth should return (current-previous)/previous\"\"\"\n        self.assertAlmostEqual(compute_growth(150, 100), 0.5)\n\n    def test_filter_by_date_range_boundary(self):\n        \"\"\"filter_by_date_range should include records on end boundary\"\"\"\n        records = [{'product': 'A', 'amount': 10, 'quantity': 1, 'date': datetime.date(2024, 1, 10)}]\n        result = filter_by_date_range(records, datetime.date(2024, 1, 1), datetime.date(2024, 1, 10))\n        self.assertEqual(len(result), 1)\n\n\n# CHECKPOINT 2\nclass TestIsolate(unittest.TestCase):\n    def test_filter_recent_days_includes_cutoff(self):\n        \"\"\"filter_recent_days should include records exactly on the cutoff date\"\"\"\n        today = datetime.date.today()\n        cutoff = today - datetime.timedelta(days=7)\n        records = [{'product': 'A', 'amount': 10, 'quantity': 1, 'date': cutoff}]\n        result = filter_recent_days(records, days=7)\n        self.assertEqual(len(result), 1)\n\n    def test_format_report_line_exact_width(self):\n        \"\"\"format_report_line should not pad when label is exactly width\"\"\"\n        label = 'x' * 30\n        line = format_report_line(label, '100')\n        self.assertEqual(len(line.split('100')[0]), 30)\n\n    def test_normalize_product_name_returns_title(self):\n        \"\"\"normalize_product_name should return Title Case\"\"\"\n        self.assertEqual(normalize_product_name('hello_world'), 'Hello World')\n\n\n# CHECKPOINT 3\nclass TestFixAndVerify(unittest.TestCase):\n    def test_deduplicate_does_not_mutate_input(self):\n        \"\"\"deduplicate_records should not alter original records\"\"\"\n        records = [{'product': 'widget', 'amount': 10, 'quantity': 1, 'date': datetime.date(2024, 1, 1)}]\n        original = records[0]['product']\n        deduplicate_records(records)\n        self.assertEqual(records[0]['product'], original)\n\n    def test_report_top_products_from_all_records(self):\n        \"\"\"generate_report top_products should be based on all records, not just recent\"\"\"\n        lines = [\n            'Widget,100.00,1,2024-01-01',\n            'Gadget,50.00,1,2024-01-01',\n            'Widget,200.00,1,2024-01-02',\n        ]\n        report = generate_report(lines)\n        self.assertIn('Widget', report['top_products'])\n        self.assertIn('$300.00', report['top_products'])\n\n    def test_aggregate_by_week_groups_correctly(self):\n        \"\"\"aggregate_by_week should sum amounts per ISO week\"\"\"\n        totals = {\n            datetime.date(2024, 1, 1): {'amount': 100, 'quantity': 1, 'transactions': 1},\n            datetime.date(2024, 1, 2): {'amount': 50, 'quantity': 1, 'transactions': 1},\n        }\n        weeks = aggregate_by_week(totals)\n        self.assertEqual(len(weeks), 1)\n        self.assertEqual(list(weeks.values())[0]['amount'], 150)\n\n\n# CHECKPOINT 4\nclass TestPostMortem(unittest.TestCase):\n    def test_compare_weeks_growth(self):\n        \"\"\"compare_weeks should compute correct growth\"\"\"\n        weeks = {\n            '2024-W01': {'amount': 200, 'quantity': 2, 'transactions': 2},\n            '2024-W02': {'amount': 300, 'quantity': 3, 'transactions': 3},\n        }\n        result = compare_weeks(weeks, '2024-W02', '2024-W01')\n        self.assertAlmostEqual(result['amount_growth'], 0.5)\n\n    def test_parse_sales_records_skips_invalid(self):\n        \"\"\"parse_sales_records should skip malformed lines\"\"\"\n        lines = ['Widget,10.0,1,2024-01-01', 'bad line', 'Gadget,5.0,2,2024-01-02']\n        records = parse_sales_records(lines)\n        self.assertEqual(len(records), 2)\n\n    def test_generate_report_counts_records(self):\n        \"\"\"generate_report should count all parsed records\"\"\"\n        lines = ['A,10,1,2024-01-01', 'B,20,1,2024-01-01']\n        report = generate_report(lines)\n        self.assertEqual(report['total_records'], 2)\n\n\nif __name__ == '__main__':\n    unittest.main()\n"},"bugs":[{"file":"parser.py","line_hint":28,"description":"compute_daily_totals() returns the input records variable instead of the computed totals dict","why_subtle":"The variable name 'records' shadows the outer parameter and the return statement uses it instead of 'totals'","prevention":"Use more distinct variable names and add return type hints"},{"file":"aggregator.py","line_hint":21,"description":"compute_growth() has operator precedence bug: current - previous / previous evaluates as current - (previous/previous) = current - 1","why_subtle":"Missing parentheses around subtraction makes the math subtly wrong for all non-zero inputs","prevention":"Always parenthesize numerator in growth formulas and add unit tests for expected values"},{"file":"filters.py","line_hint":20,"description":"filter_recent_days() uses strict < instead of <=, silently dropping records exactly on the cutoff date","why_subtle":"Date boundary bugs are invisible in large datasets; the data just looks slightly smaller","prevention":"Write explicit boundary tests for inclusive/exclusive ranges"},{"file":"normalizer.py","line_hint":25,"description":"deduplicate_records() mutates the original input records by normalizing product names in-place","why_subtle":"The function returns a deduplicated list, so callers don't notice their original list was modified","prevention":"Never mutate input data structures; always create copies before modifying"},{"file":"reporter.py","line_hint":12,"description":"generate_report() passes recent (last 7 days) records to top_products instead of all records, skewing rankings","why_subtle":"The report generates output without errors, but the business insight is wrong because the scope is narrowed","prevention":"Name variables clearly (recent_records vs all_records) and verify report outputs against known data"}],"checkpoints":[{"id":1,"title":"Reproduce","ai_enabled":false,"task":"Run the full test suite. For each failing test, add a comment in the relevant file identifying which function you think is responsible and why. Annotate at least 4 of the 5 bugs before proceeding."},{"id":2,"title":"Isolate","ai_enabled":true,"task":"Using the AI as a sounding board, narrow down the exact lines causing bugs #1, #2, and #3. Explain your reasoning in chat for each one."},{"id":3,"title":"Fix & Verify","ai_enabled":true,"task":"Patch all 5 bugs. Run tests after each individual fix — do not fix everything at once. All 10 tests must pass."},{"id":4,"title":"Post-mortem","ai_enabled":true,"task":"In the chat, explain each bug: root cause, why it was hard to spot, and how you would prevent it in production."}],"stubs":[]},{"id":"debug:seed:1","domain":"Order Processing Pipeline","files":[{"name":"orders.py","content":"import datetime\n\n\ndef parse_order(raw):\n    order = {\n        'id': raw.get('id'),\n        'customer': raw.get('customer', ''),\n        'items': raw.get('items', []),\n        'placed_at': raw.get('placed_at') or datetime.datetime.now(),\n        'status': raw.get('status', 'pending'),\n    }\n    return order\n\n\ndef calculate_subtotal(items):\n    total = 0\n    for item in items:\n        price = item.get('unit_price', 0)\n        qty = item.get('quantity', 0)\n        # BUG: operator precedence - discount applied to qty only, not the product\n        total += price * qty - item.get('discount', 0)\n    return total\n\n\ndef apply_shipping(subtotal, region='domestic'):\n    if subtotal >= 100:\n        return 0\n    rates = {'domestic': 5.0, 'international': 15.0}\n    return rates.get(region, 5.0)\n\n\ndef compute_total(order):\n    items = order.get('items', [])\n    subtotal = calculate_subtotal(items)\n    shipping = apply_shipping(subtotal, order.get('region', 'domestic'))\n    return subtotal + shipping\n"},{"name":"discounts.py","content":"import datetime\n\n\ndef apply_coupon(subtotal, coupon_code):\n    if not coupon_code:\n        return subtotal\n    if coupon_code == 'SAVE10':\n        return subtotal * 0.90\n    if coupon_code == 'SAVE20':\n        return subtotal * 0.80\n    if coupon_code == 'BOGO':\n        # BUG: returns the discount amount instead of subtracting from subtotal\n        return subtotal * 0.50\n    return subtotal\n\n\ndef seasonal_discount(subtotal, month=None):\n    if month is None:\n        month = datetime.datetime.now().month\n    if month == 12:\n        return subtotal * 0.95\n    if month == 11:\n        return subtotal * 0.90\n    return subtotal\n\n\ndef bulk_discount(subtotal, item_count):\n    if item_count >= 50:\n        return subtotal * 0.85\n    if item_count >= 20:\n        return subtotal * 0.90\n    # BUG: off-by-one on the boundary - 10 items should get 5% off but don't\n    if item_count > 10:\n        return subtotal * 0.95\n    return subtotal\n"},{"name":"taxes.py","content":"TAX_RATES = {\n    'CA': 0.0825,\n    'NY': 0.08,\n    'TX': 0.0625,\n}\n\n\ndef compute_tax(amount, state):\n    rate = TAX_RATES.get(state, 0.0)\n    # BUG: string coercion — returns string when state is not found\n    if rate == 0.0:\n        return '0.00'\n    return round(amount * rate, 2)\n\n\ndef tax_included_total(subtotal, state):\n    tax = compute_tax(subtotal, state)\n    return subtotal + tax\n"},{"name":"shipping.py","content":"import datetime\n\n\ndef estimate_delivery(region, shipping_speed='standard'):\n    base_days = {'standard': 5, 'express': 2, 'overnight': 1}\n    # BUG: weekend logic is inverted — adds days instead of skipping weekends\n    today = datetime.date.today()\n    days = base_days.get(shipping_speed, 5)\n    delivery = today + datetime.timedelta(days=days)\n    while delivery.weekday() >= 5:\n        days += 1\n        delivery = today + datetime.timedelta(days=days)\n    return delivery\n\n\ndef split_shipment(items, max_per_box=3):\n    boxes = []\n    current = []\n    for item in items:\n        current.append(item)\n        if len(current) == max_per_box:\n            boxes.append(current)\n            current = []\n    if current:\n        boxes.append(current)\n    return boxes\n\n\ndef format_address(address):\n    lines = [\n        address.get('name', ''),\n        address.get('street', ''),\n        f\"{address.get('city', '')}, {address.get('state', '')} {address.get('zip', '')}\",\n    ]\n    return '\\n'.join(lines)\n"},{"name":"invoices.py","content":"from orders import compute_total\nfrom discounts import apply_coupon, seasonal_discount\nfrom taxes import tax_included_total\nfrom shipping import estimate_delivery\n\n\ndef generate_invoice(order):\n    items = order.get('items', [])\n    subtotal = compute_total(order) - estimate_delivery(order.get('region'))\n    # wait, that is wrong for structure. Let's recalculate properly:\n    subtotal = sum(i.get('unit_price', 0) * i.get('quantity', 0) for i in items)\n    after_coupon = apply_coupon(subtotal, order.get('coupon'))\n    after_seasonal = seasonal_discount(after_coupon)\n    total_with_tax = tax_included_total(after_seasonal, order.get('state', ''))\n    delivery_date = estimate_delivery(order.get('region', 'domestic'), order.get('speed', 'standard'))\n    return {\n        'order_id': order.get('id'),\n        'subtotal': round(subtotal, 2),\n        'total': round(total_with_tax, 2),\n        'delivery_estimate': delivery_date.isoformat(),\n        'item_count': len(items),\n    }\n\n\ndef batch_invoices(orders):\n    results = []\n    for order in orders:\n        inv = generate_invoice(order)\n        results.append(inv)\n    return results\n\n\ndef summarize_revenue(invoices):\n    total = 0\n    by_state = {}\n    for inv in invoices:\n        total += inv['total']\n        state = inv.get('state', 'UNKNOWN')\n        by_state[state] = by_state.get(state, 0) + inv['total']\n    return {'total': total, 'by_state': by_state}\n"},{"name":"routing.py","content":"WAREHOUSES = {\n    'West': ['CA', 'OR', 'WA', 'NV', 'AZ'],\n    'East': ['NY', 'NJ', 'PA', 'MA', 'CT'],\n    'Central': ['TX', 'IL', 'CO', 'MN', 'WI'],\n}\n\n\ndef find_warehouse(state):\n    for region, states in WAREHOUSES.items():\n        if state in states:\n            return region\n    return 'Central'\n\n\ndef allocate_inventory(items, inventory):\n    allocation = {}\n    for item in items:\n        sku = item['sku']\n        qty = item['quantity']\n        # BUG: mutates inventory dict in place instead of working on a copy\n        available = inventory.get(sku, 0)\n        if available >= qty:\n            inventory[sku] = available - qty\n            allocation[sku] = qty\n        else:\n            allocation[sku] = available\n            inventory[sku] = 0\n    return allocation\n\n\ndef route_order(order, inventory):\n    state = order.get('state', '')\n    warehouse = find_warehouse(state)\n    allocation = allocate_inventory(order.get('items', []), inventory)\n    return {\n        'warehouse': warehouse,\n        'allocation': allocation,\n        'fulfilled': sum(allocation.values()) == sum(i['quantity'] for i in order.get('items', [])),\n    }\n"}],"test_file":{"name":"test_solution.py","content":"import datetime\nimport unittest\nfrom orders import calculate_subtotal, compute_total\nfrom discounts import apply_coupon, bulk_discount\nfrom taxes import compute_tax, tax_included_total\nfrom shipping import estimate_delivery\nfrom invoices import generate_invoice\nfrom routing import allocate_inventory, route_order\n\n\n# CHECKPOINT 1\nclass TestReproduce(unittest.TestCase):\n    def test_calculate_subtotal_with_discount(self):\n        \"\"\"Subtotal should apply discount to the line total, not subtract from qty\"\"\"\n        items = [{'unit_price': 10, 'quantity': 2, 'discount': 3}]\n        result = calculate_subtotal(items)\n        self.assertEqual(result, 17.0)\n\n    def test_compute_tax_returns_numeric(self):\n        \"\"\"compute_tax should always return a numeric type\"\"\"\n        tax = compute_tax(100, 'FL')\n        self.assertIsInstance(tax, (int, float))\n\n    def test_tax_included_total_with_zero_rate(self):\n        \"\"\"tax_included_total should work even with zero/unknown tax rate\"\"\"\n        total = tax_included_total(100, 'FL')\n        self.assertEqual(total, 100.0)\n\n\n# CHECKPOINT 2\nclass TestIsolate(unittest.TestCase):\n    def test_apply_coupon_bogo(self):\n        \"\"\"BOGO coupon should return discounted subtotal, not the discount amount\"\"\"\n        result = apply_coupon(100, 'BOGO')\n        self.assertEqual(result, 50.0)\n\n    def test_bulk_discount_boundary(self):\n        \"\"\"bulk_discount should apply at exactly the boundary\"\"\"\n        result = bulk_discount(100, 10)\n        self.assertEqual(result, 95.0)\n\n    def test_allocate_inventory_does_not_mutate(self):\n        \"\"\"allocate_inventory should not modify the input inventory dict\"\"\"\n        inv = {'SKU1': 5, 'SKU2': 3}\n        original = dict(inv)\n        allocate_inventory([{'sku': 'SKU1', 'quantity': 2}], inv)\n        self.assertEqual(inv, original)\n\n\n# CHECKPOINT 3\nclass TestFixAndVerify(unittest.TestCase):\n    def test_estimate_delivery_skips_weekends(self):\n        \"\"\"estimate_delivery should not land on a weekend\"\"\"\n        delivery = estimate_delivery('domestic', 'standard')\n        self.assertLess(delivery.weekday(), 5)\n\n    def test_generate_invoice_correct_total(self):\n        \"\"\"generate_invoice should correctly apply coupon and tax\"\"\"\n        order = {\n            'id': 'O1',\n            'items': [{'unit_price': 50, 'quantity': 2}],\n            'coupon': 'SAVE10',\n            'state': 'NY',\n            'region': 'domestic',\n            'speed': 'standard',\n        }\n        inv = generate_invoice(order)\n        expected = round(100 * 0.90 * 1.08, 2)\n        self.assertEqual(inv['total'], expected)\n\n    def test_route_order_calculates_fulfillment(self):\n        \"\"\"route_order should mark fulfilled when all items allocated\"\"\"\n        order = {\n            'state': 'CA',\n            'items': [{'sku': 'A', 'quantity': 2}],\n        }\n        inv = {'A': 5}\n        result = route_order(order, inv)\n        self.assertTrue(result['fulfilled'])\n        self.assertEqual(result['allocation']['A'], 2)\n\n\n# CHECKPOINT 4\nclass TestPostMortem(unittest.TestCase):\n    def test_compute_total_with_shipping_discount(self):\n        \"\"\"compute_total should give free shipping over $100\"\"\"\n        order = {\n            'items': [{'unit_price': 60, 'quantity': 2}],\n            'region': 'domestic',\n        }\n        total = compute_total(order)\n        self.assertEqual(total, 120.0)\n\n    def test_calculate_subtotal_multiple_items(self):\n        \"\"\"calculate_subtotal should sum multiple item lines correctly\"\"\"\n        items = [\n            {'unit_price': 10, 'quantity': 1, 'discount': 0},\n            {'unit_price': 20, 'quantity': 2, 'discount': 5},\n        ]\n        result = calculate_subtotal(items)\n        self.assertEqual(result, 45.0)\n\n    def test_bulk_discount_tiers(self):\n        \"\"\"bulk_discount should apply correct tier\"\"\"\n        self.assertEqual(bulk_discount(100, 50), 85.0)\n        self.assertEqual(bulk_discount(100, 20), 90.0)\n        self.assertEqual(bulk_discount(100, 10), 95.0)\n\n\nif __name__ == '__main__':\n    unittest.main()\n"},"bugs":[{"file":"orders.py","line_hint":17,"description":"calculate_subtotal() has operator precedence bug: discount is subtracted from qty before multiplying by price","why_subtle":"PEMDAS means 'price * qty - discount' is parsed as 'price * (qty - discount)', silently undercharging","prevention":"Always parenthesize arithmetic expressions and write unit tests with expected totals"},{"file":"discounts.py","line_hint":15,"description":"apply_coupon() returns the discounted value for BOGO instead of subtracting discount from subtotal","why_subtle":"All other coupon branches return correct final values; BOGO accidentally returns the amount off rather than the new total","prevention":"Add assertions in tests for every coupon tier"},{"file":"discounts.py","line_hint":29,"description":"bulk_discount() uses strict > instead of >= for the 10-item boundary","why_subtle":"Orders with exactly 10 items silently miss the 5% discount","prevention":"Always test boundary conditions exactly at the threshold"},{"file":"taxes.py","line_hint":12,"description":"compute_tax() returns a string '0.00' for unknown states instead of 0.0","why_subtle":"No exception is thrown; downstream code silently concatenates or miscalculates because type is wrong","prevention":"Use static type hints and return type assertions in unit tests"},{"file":"routing.py","line_hint":21,"description":"allocate_inventory() mutates the input inventory dictionary in place","why_subtle":"The function returns correct allocation, but the caller's inventory is permanently reduced","prevention":"Copy mutable inputs at function entry; treat all inputs as read-only by default"}],"checkpoints":[{"id":1,"title":"Reproduce","ai_enabled":false,"task":"Run the full test suite. For each failing test, add a comment in the relevant file identifying which function you think is responsible and why. Annotate at least 4 of the 5 bugs before proceeding."},{"id":2,"title":"Isolate","ai_enabled":true,"task":"Using the AI as a sounding board, narrow down the exact lines causing bugs #1, #2, and #3. Explain your reasoning in chat for each one."},{"id":3,"title":"Fix & Verify","ai_enabled":true,"task":"Patch all 5 bugs. Run tests after each individual fix. All 10 tests must pass."},{"id":4,"title":"Post-mortem","ai_enabled":true,"task":"In the chat, explain each bug: root cause, why it was hard to spot, and how you would prevent it in production."}],"stubs":[]}];
